def main():
    assert len(PREDICTIONS) == 20, f"预测条数不为20：{len(PREDICTIONS)}"
    ids = [p["case_id"] for p in PREDICTIONS]
    assert set(ids) == set(BATCH_IDS), f"id集与本批不一致：{sorted(set(ids) ^ set(BATCH_IDS))}"
    assert len(set(ids)) == 20, "id有重复"
    for p in PREDICTIONS:
        assert set(p.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, p["case_id"]
        assert isinstance(p["confidence"], float) and 0.0 <= p["confidence"] <= 1.0, p["case_id"]
        t = p["trigger"]
        assert set(t.keys()) == {"changed_main", "reserve_used", "disputed", "reason"}, p["case_id"]
        assert all(isinstance(t[k], bool) for k in ("changed_main", "reserve_used", "disputed")), p["case_id"]
        assert p["basis"].startswith("tradition: liuyao"), p["case_id"]
        assert "第八节功量核" in p["basis"] and "主线认定行" in p["basis"], p["case_id"]
    os.makedirs(OUT_DIR, exist_ok=True)
    written = 0
    for p in PREDICTIONS:
        path = os.path.join(OUT_DIR, p["case_id"] + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(p, f, ensure_ascii=False, indent=2)
            f.write("\n")
        written += 1
    assert written == 20, f"写出文件数不为20：{written}"
    cm = sum(1 for p in PREDICTIONS if p["trigger"]["changed_main"])
    ru = sum(1 for p in PREDICTIONS if p["trigger"]["reserve_used"])
    di = sum(1 for p in PREDICTIONS if p["trigger"]["disputed"])
    print(f"cases={len(PREDICTIONS)} written={written} changed_main={cm} reserve_used={ru} disputed={di}")


if __name__ == "__main__":
    main()
